}
.result-text {
    background: white;
    padding: 16px;
    border-radius: 8px;
    font-family: 'Consolas', 'Courier New', monospace;
    font-size: 15px;
    border: 1px solid #e0e0e0;
    min-height: 48px;
    display: flex;
    align-items: center;
}
.status {
    margin-top: 15px;
    padding: 12px;
    border-radius: 8px;
    font-size: 14px;
    text-align: center;
    font-weight: 500;
}
